import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract high_ts from watermark (single row)
    high_ts = watermark["high_ts"].iloc[0]

    # Filter events that are new (beyond watermark) and within or at watermark
    # We only process events with event_ts <= high_ts that haven't been applied yet
    # Assumption: last_event_ts in target_snapshot marks the last applied event

    # Sort events by item_id, then by (event_ts, event_seq) for deterministic processing
    cdc_events = cdc_events.sort_values(
        by=["item_id", "event_ts", "event_seq"],
        ascending=[True, True, True]
    ).reset_index(drop=True)

    # Filter to only events at or before the watermark
    cdc_events = cdc_events[cdc_events["event_ts"] <= high_ts].copy()

    # Build a dict to track current state: item_id -> (qty_on_hand, last_event_ts)
    state = {}
    for _, row in target_snapshot.iterrows():
        item_id = row["item_id"]
        state[item_id] = {
            "qty_on_hand": row["qty_on_hand"],
            "last_event_ts": row["last_event_ts"]
        }

    # Apply events sequentially per item
    for _, event in cdc_events.iterrows():
        item_id = event["item_id"]
        event_ts = event["event_ts"]
        event_seq = event["event_seq"]
        op = event["op"]
        qty = event["qty"]

        # Only apply if this event is newer than the last applied event for this item
        if item_id not in state:
            last_applied_ts = pd.Timestamp.min
        else:
            last_applied_ts = state[item_id]["last_event_ts"]

        # Apply event if it's newer, or if same timestamp, by event_seq order
        should_apply = False
        if pd.isna(last_applied_ts):
            should_apply = True
        elif event_ts > last_applied_ts:
            should_apply = True
        elif event_ts == last_applied_ts:
            # For same timestamp, we need to compare by event_seq
            # But we don't store event_seq in state, so we apply in order processed
            # This is handled by sorting before the loop
            should_apply = True

        if should_apply:
            if op == "R":  # Receipt: add to qty
                if item_id not in state:
                    state[item_id] = {"qty_on_hand": 0.0, "last_event_ts": event_ts}
                state[item_id]["qty_on_hand"] += qty
                state[item_id]["last_event_ts"] = event_ts
            elif op == "A":  # Adjustment: set absolute qty
                if item_id not in state:
                    state[item_id] = {"qty_on_hand": qty, "last_event_ts": event_ts}
                else:
                    state[item_id]["qty_on_hand"] = qty
                    state[item_id]["last_event_ts"] = event_ts
            elif op == "D":  # Delete: remove from state
                if item_id in state:
                    del state[item_id]

    # Build output snapshot
    rows = []
    for item_id, item_state in state.items():
        rows.append({
            "item_id": item_id,
            "qty_on_hand": item_state["qty_on_hand"],
            "last_event_ts": item_state["last_event_ts"]
        })

    if rows:
        new_snapshot = pd.DataFrame(rows)
        new_snapshot = new_snapshot.sort_values("item_id").reset_index(drop=True)
    else:
        new_snapshot = pd.DataFrame(columns=["item_id", "qty_on_hand", "last_event_ts"])

    # Ensure correct dtypes
    new_snapshot["item_id"] = new_snapshot["item_id"].astype("int64")
    new_snapshot["qty_on_hand"] = new_snapshot["qty_on_hand"].astype("float64")
    new_snapshot["last_event_ts"] = pd.to_datetime(new_snapshot["last_event_ts"], utc=False).dt.as_unit("us")

    return {"new_snapshot": new_snapshot}
